<?php require_once __DIR__.'/../../includes/admin-check.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM solusi WHERE id=?');$q->execute([$id]);$data=$q->fetch();if(!$data){http_response_code(404);exit('Solusi tidak ditemukan');}$faults=$pdo->query('SELECT id,kode,nama FROM kerusakan ORDER BY kode')->fetchAll();$pageTitle='Edit solusi';require __DIR__.'/../../includes/header.php';?><h1>Edit solusi</h1><form method="post" action="update.php" class="card form"><?=csrf_field()?><?php if(isset($id)):?><input type="hidden" name="id" value="<?=$id?>"><?php endif?><label>Kerusakan<select name="kerusakan_id" required><option value="">Pilih kerusakan</option><?php foreach($faults as $f):?><option value="<?=$f['id']?>" <?=((int)($data['kerusakan_id']??0)===(int)$f['id'])?'selected':''?>><?=e($f['kode'].' - '.$f['nama'])?></option><?php endforeach?></select></label><label>Deskripsi solusi<textarea name="deskripsi" required><?=e($data['deskripsi']??'')?></textarea></label><button class="button">Simpan</button></form><?php require __DIR__.'/../../includes/footer.php';?>